import './StatusList.css';
import type { Item, Status } from '../../types';

export const STATUS_LABELS: Record<Status, string> = {
  'todo': 'To Do',
  'in-progress': 'In Progress',
  'review': 'In Review',
  'done': 'Done',
  'blocked': 'Blocked',
  'cancelled': 'Cancelled',
};

export const SKELETON_COUNT = 6;

export function statusColor(status: Status): string {
  switch (status) {
    case 'todo': return 'status-todo';
    case 'in-progress': return 'status-in-progress';
    case 'review': return 'status-review';
    case 'done': return 'status-done';
    case 'blocked': return 'status-blocked';
    case 'cancelled': return 'status-cancelled';
  }
}

function isStatus(value: string): value is Status {
  return Object.prototype.hasOwnProperty.call(STATUS_LABELS, value);
}

function groupByStatus(items: Item[]): Array<[Status, Item[]]> {
  const order = Object.keys(STATUS_LABELS).filter(isStatus);
  return order
    .map((status): [Status, Item[]] => [
      status,
      items.filter((item) => item.status === status),
    ])
    .filter(([, group]) => group.length > 0);
}

interface StatusListProps {
  items: Item[] | null;
}

export function StatusList({ items }: StatusListProps): JSX.Element {
  if (items === null) {
    return (
      <ul className="status-list" aria-label="Status list" aria-busy="true">
        {Array.from({ length: SKELETON_COUNT }).map((_, i) => (
          <li key={i} className="skeleton-item">
            <span className="skeleton-pill" />
          </li>
        ))}
      </ul>
    );
  }

  const groups = groupByStatus(items);

  return (
    <ul className="status-list" aria-label="Status list">
      {groups.map(([status, groupItems]) => (
        <li key={status} className="status-group">
          <span className={`status-badge ${statusColor(status)}`}>
            {STATUS_LABELS[status]}
          </span>
          <ul>
            {groupItems.map((item) => (
              <li key={item.id} className="status-item">
                {item.title}
              </li>
            ))}
          </ul>
        </li>
      ))}
    </ul>
  );
}

