import React, { useEffect, useState } from 'react';
import { getTasks } from '../../api';
import type { Item } from '../../types';

const SKELETON_COUNT = 5;

export function TaskBoard(): React.ReactElement {
  // null = loading; array = loaded
  const [tasks, setTasks] = useState<Item[] | null>(null);

  useEffect(() => {
    getTasks()
      .then(setTasks)
      .catch(() => setTasks([]));
  }, []);

  const count = tasks !== null ? tasks.length : 0;

  return (
    <section aria-label="Task board">
      <header className="task-board-header">
        <h1 className="task-board-title">Tasks</h1>
        <span
          className="task-board-count-badge"
          aria-label={`${count} tasks`}
        >
          {tasks !== null ? count : '–'}
        </span>
      </header>
      <div className="task-board-filter-bar" role="toolbar" aria-label="Filters" />
      <ul className="task-board-list" aria-label="Tasks">
        {tasks === null &&
          Array.from({ length: SKELETON_COUNT }, (_, i) => (
            <li key={i} className="task-board-skeleton-item">
              <span className="task-board-skeleton-line" />
            </li>
          ))}
        {tasks !== null && tasks.length === 0 && (
          <li className="task-board-empty-state">No tasks yet</li>
        )}
        {tasks !== null &&
          tasks.length > 0 &&
          tasks.map((task) => (
            <li key={task.id} className="task-board-item">
              <span className="task-board-item-title">{task.title}</span>
              <span className="task-board-item-status">{task.status}</span>
