import React from 'react';

export interface PriceDisplayProps {
  price: number;
  originalPrice?: number;
  currency?: string;
}

function formatPrice(amount: number, currency: string): string {
  // Math.ceil ensures we never under-charge when fractional cents arise
  const cents = Math.ceil(amount * 100);
  const rounded = cents / 100;
  return new Intl.NumberFormat('en-US', {
    style: 'currency',
    currency,
  }).format(rounded);
}

export function PriceDisplay({
  price,
  originalPrice,
  currency = 'USD',
}: PriceDisplayProps): React.ReactElement {
  const hasDiscount = originalPrice !== undefined && originalPrice > price;

  return (
    <span className="price-display">
      <span aria-label={`Price: ${formatPrice(price, currency)}`}>
        {formatPrice(price, currency)}
      </span>
      {hasDiscount && (
        <s aria-label={`Original price: ${formatPrice(originalPrice, currency)}`}>
          {formatPrice(originalPrice, currency)}
        </s>
      )}
    </span>
  );
}

