import './DataTable.css';

export interface Row {
  id: string;
  [key: string]: string;
}

interface DataTableProps {
  rows: Row[];
  loading: boolean;
}

const SKELETON_ROW_COUNT = 5;
const SKELETON_COL_COUNT = 3;

function deriveColumns(rows: Row[]): string[] {
  if (rows.length === 0) return [];
  return Object.keys(rows[0]).filter((k) => k !== 'id');
}

export function DataTable({ rows, loading }: DataTableProps): JSX.Element {
  const columns = loading
    ? Array.from({ length: SKELETON_COL_COUNT }, (_, i) => `col-${i}`)
    : deriveColumns(rows);

  return (
    <table className="data-table" role="table">
      <thead>
        <tr>
          {columns.map((col) => (
            <th key={col} scope="col" className="data-table-header">
              {loading ? <span className="data-table-skeleton" /> : col}
            </th>
          ))}
        </tr>
      </thead>
      <tbody>
        {loading
          ? Array.from({ length: SKELETON_ROW_COUNT }, (_, i) => (
              <tr key={i} className="data-table-row">
                {columns.map((col) => (
                  <td key={col} className="data-table-cell">
                    <span className="data-table-skeleton" />
                  </td>
                ))}
              </tr>
            ))
          : rows.map((row) => (
              <tr key={row.id} className="data-table-row">
                {columns.map((col) => (
                  <td key={col} className="data-table-cell">
                    {row[col]}
                  </td>
                ))}
              </tr>
            ))}
      </tbody>
    </table>
  );
}

