import './ChipBar.css';
import type { Status } from '../../types';

interface ChipBarProps {
  statuses: Status[];
  selected: Set<Status>;
  onSelectionChange: (selected: Set<Status>) => void;
}

export function ChipBar({ statuses, selected, onSelectionChange }: ChipBarProps): JSX.Element {
  function handleClick(status: Status): void {
    const next = new Set(selected);
    if (next.has(status)) {
      next.delete(status);
    } else {
      next.add(status);
    }
    onSelectionChange(next);
  }

  return (
    <div className="chip-bar" role="toolbar" aria-label="Filter by status">
      {statuses.map((status) => {
        const pressed = selected.has(status);
        return (
          <button
            key={status}
            className={`chip${pressed ? ' chip--pressed' : ''}`}
            aria-pressed={pressed}
            onClick={() => handleClick(status)}
          >
            {status}
          </button>
        );
      })}
    </div>
  );
}

